package cli

import (
	"bytes"
	"encoding/json"
	"testing"
)

func TestWriteSyncEventEscapesJSONFields(t *testing.T) {
	const message = "line 1\nline 2 with \"quotes\" and \\backslashes"

	var out bytes.Buffer
	writeSyncEvent(&out, map[string]any{
		"event":   "sync_error",
		"message": message,
	})

	var decoded map[string]string
	if err := json.Unmarshal(out.Bytes(), &decoded); err != nil {
		t.Fatalf("sync event is not valid JSON: %v\n%s", err, out.String())
	}
	if decoded["message"] != message {
		t.Fatalf("message = %q, want %q", decoded["message"], message)
	}
}
